import path from "node:path";

import { migrate } from "drizzle-orm/postgres-js/migrator";

import { createDb } from "./connection";

export const MIGRATIONS_FOLDER = path.resolve(import.meta.dirname, "migrations");

/**
 * Apply pending SQL migrations (generated by `npm run db:generate`).
 * This is the only supported way to change the production schema —
 * never `drizzle-kit push` (spec §16.9).
 */
export async function runMigrations(databaseUrl: string, migrationsFolder = MIGRATIONS_FOLDER) {
  const { db, client } = createDb(databaseUrl, { max: 1 });
  try {
    await migrate(db, { migrationsFolder });
  } finally {
    await client.end();
  }
}
